using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class FrontWalkCycleInstall {
 public static void Run(){string root="Assets/Shioka/調整Data/Fighter/Awari/Move/ForwardWalk/";string[] names={"01-contact-A.png","02-passing-near-support.png","03-contact-B.png","04-passing-far-support.png"};int[] soles={1500,1503,1471,1485};var action=AssetDatabase.LoadAssetAtPath<TrainingMotionAction>(root+"ForwardWalk.asset");if(action==null||action.poses.Length!=1)throw new Exception("Expected unchanged one-pose motion action");var old=action.poses[0];var poses=new TrainingMotionPose[4];for(int i=0;i<4;i++){string path=root+"Sprites/ApprovedCycle4/"+names[i];var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.alphaIsTransparency=true;importer.mipmapEnabled=false;importer.spritePixelsPerUnit=700;var settings=new TextureImporterSettings();importer.ReadTextureSettings(settings);settings.spriteAlignment=9;settings.spritePivot=new Vector2(.55f,(1536-soles[i])/1536f);importer.SetTextureSettings(settings);importer.SaveAndReimport();poses[i]=new TrainingMotionPose{sprite=AssetDatabase.LoadAssetAtPath<Sprite>(path),holdFrames=4,visualOffset=old.visualOffset,hurt=old.hurt.Select(h=>new TrainingMotionHurt{partId=h.partId,center=h.center,size=h.size}).ToArray()};}action.poses=poses;if(!action.Validate(out var error))throw new Exception(error);EditorUtility.SetDirty(action);AssetDatabase.SaveAssetIfDirty(action);Debug.Log("FrontWalk cycle1-2-3-4 loop, 4F each =16F; movement unchanged; 700PPU same scale, sole pivots");}
}
